-- E-commerce & Retail Analytics Dataset for Power BI Portfolio
-- SQL Server / T-SQL compatible. Synthetic Amazon-style sample data; not real Amazon data.
-- Run this script in SQL Server Management Studio or Azure Data Studio.
-- Main model: Regions -> Customers -> Orders -> Sales -> Returns; Products -> Sales.
SET NOCOUNT ON;

-- Re-runnable setup: drop views and tables in dependency order
IF OBJECT_ID('dbo.vw_DailyPerformance','V') IS NOT NULL DROP VIEW dbo.vw_DailyPerformance;
IF OBJECT_ID('dbo.vw_ProductRegionSales','V') IS NOT NULL DROP VIEW dbo.vw_ProductRegionSales;
IF OBJECT_ID('dbo.Returns','U') IS NOT NULL DROP TABLE dbo.Returns;
IF OBJECT_ID('dbo.Sales','U') IS NOT NULL DROP TABLE dbo.Sales;
IF OBJECT_ID('dbo.Orders','U') IS NOT NULL DROP TABLE dbo.Orders;
IF OBJECT_ID('dbo.Products','U') IS NOT NULL DROP TABLE dbo.Products;
IF OBJECT_ID('dbo.Customers','U') IS NOT NULL DROP TABLE dbo.Customers;
IF OBJECT_ID('dbo.Regions','U') IS NOT NULL DROP TABLE dbo.Regions;

CREATE TABLE dbo.Regions (RegionID INT PRIMARY KEY, RegionName NVARCHAR(50) NOT NULL, MainCity NVARCHAR(50) NOT NULL, Country NVARCHAR(50) NOT NULL);
CREATE TABLE dbo.Customers (CustomerID INT PRIMARY KEY, FirstName NVARCHAR(50) NOT NULL, LastName NVARCHAR(50) NOT NULL, Email NVARCHAR(120) NOT NULL UNIQUE, SignupDate DATE NOT NULL, Segment NVARCHAR(20) NOT NULL CHECK (Segment IN ('Consumer','Corporate','Small Business')), RegionID INT NOT NULL FOREIGN KEY REFERENCES dbo.Regions(RegionID));
CREATE TABLE dbo.Products (ProductID INT PRIMARY KEY, ProductName NVARCHAR(100) NOT NULL, Category NVARCHAR(50) NOT NULL, Subcategory NVARCHAR(50) NOT NULL, UnitPrice DECIMAL(10,2) NOT NULL CHECK (UnitPrice >= 0), UnitCost DECIMAL(10,2) NOT NULL CHECK (UnitCost >= 0), IsActive BIT NOT NULL DEFAULT 1);
CREATE TABLE dbo.Orders (OrderID INT PRIMARY KEY, CustomerID INT NOT NULL FOREIGN KEY REFERENCES dbo.Customers(CustomerID), OrderDate DATE NOT NULL, ShipDate DATE NULL, OrderStatus NVARCHAR(20) NOT NULL CHECK (OrderStatus IN ('Delivered','Shipped','Processing','Cancelled')), SalesChannel NVARCHAR(20) NOT NULL CHECK (SalesChannel IN ('Website','Mobile App','Marketplace')), PaymentMethod NVARCHAR(20) NOT NULL);
CREATE TABLE dbo.Sales (SaleID INT PRIMARY KEY, OrderID INT NOT NULL FOREIGN KEY REFERENCES dbo.Orders(OrderID), ProductID INT NOT NULL FOREIGN KEY REFERENCES dbo.Products(ProductID), Quantity INT NOT NULL CHECK (Quantity > 0), UnitPrice DECIMAL(10,2) NOT NULL, UnitCost DECIMAL(10,2) NOT NULL, DiscountPct DECIMAL(5,2) NOT NULL DEFAULT 0 CHECK (DiscountPct >= 0 AND DiscountPct <= 100), SalesAmount AS (CONVERT(DECIMAL(12,2), Quantity * UnitPrice * (1 - DiscountPct / 100.0))) PERSISTED, CostAmount AS (CONVERT(DECIMAL(12,2), Quantity * UnitCost)) PERSISTED, GrossProfit AS (CONVERT(DECIMAL(12,2), Quantity * UnitPrice * (1 - DiscountPct / 100.0) - Quantity * UnitCost)) PERSISTED);
CREATE TABLE dbo.Returns (ReturnID INT PRIMARY KEY, SaleID INT NOT NULL FOREIGN KEY REFERENCES dbo.Sales(SaleID), ReturnDate DATE NOT NULL, ReturnQuantity INT NOT NULL CHECK (ReturnQuantity > 0), ReturnReason NVARCHAR(40) NOT NULL, RefundAmount DECIMAL(12,2) NOT NULL CHECK (RefundAmount >= 0), ReturnStatus NVARCHAR(20) NOT NULL CHECK (ReturnStatus IN ('Approved','Pending','Rejected')));

