-- Reporting view: daily gross sales, approved refunds, net revenue, estimated COGS and net profit.
-- Sales are recognized for non-cancelled orders; approved returns reduce net revenue and profit.
GO

CREATE VIEW dbo.vw_DailyPerformance AS
WITH DailySales AS (
  SELECT o.OrderDate AS [Date],
         SUM(CASE WHEN o.OrderStatus <> 'Cancelled' THEN s.SalesAmount ELSE 0 END) AS GrossRevenue,
         SUM(CASE WHEN o.OrderStatus <> 'Cancelled' THEN s.CostAmount ELSE 0 END) AS CostOfGoodsSold,
         SUM(CASE WHEN o.OrderStatus <> 'Cancelled' THEN s.GrossProfit ELSE 0 END) AS GrossProfit,
         SUM(CASE WHEN o.OrderStatus <> 'Cancelled' THEN s.Quantity ELSE 0 END) AS UnitsSold
  FROM dbo.Orders o JOIN dbo.Sales s ON s.OrderID = o.OrderID GROUP BY o.OrderDate
), ApprovedReturns AS (
  SELECT r.ReturnDate AS [Date], SUM(r.RefundAmount) AS ApprovedRefunds
  FROM dbo.Returns r WHERE r.ReturnStatus = 'Approved' GROUP BY r.ReturnDate
)
SELECT ds.[Date], ds.GrossRevenue, ds.CostOfGoodsSold, ds.GrossProfit, ds.UnitsSold,
       COALESCE(ar.ApprovedRefunds, 0) AS ApprovedRefunds,
       CONVERT(DECIMAL(12,2), ds.GrossRevenue - COALESCE(ar.ApprovedRefunds,0)) AS NetRevenue,
       CONVERT(DECIMAL(12,2), ds.GrossProfit - COALESCE(ar.ApprovedRefunds,0)) AS NetProfit
FROM DailySales ds LEFT JOIN ApprovedReturns ar ON ar.[Date] = ds.[Date];

-- Reporting view: product + customer region sales for Power BI product/region analysis.
GO

CREATE VIEW dbo.vw_ProductRegionSales AS
SELECT p.ProductID, p.ProductName, p.Category, p.Subcategory,
       rg.RegionID, rg.RegionName, rg.Country,
       o.OrderDate, o.OrderStatus, o.SalesChannel,
       COUNT(DISTINCT o.OrderID) AS OrderCount,
       SUM(CASE WHEN o.OrderStatus <> 'Cancelled' THEN s.Quantity ELSE 0 END) AS UnitsSold,
       CONVERT(DECIMAL(12,2), SUM(CASE WHEN o.OrderStatus <> 'Cancelled' THEN s.SalesAmount ELSE 0 END)) AS GrossRevenue,
       CONVERT(DECIMAL(12,2), SUM(CASE WHEN o.OrderStatus <> 'Cancelled' THEN s.GrossProfit ELSE 0 END)) AS GrossProfit
FROM dbo.Sales s
JOIN dbo.Products p ON p.ProductID = s.ProductID
JOIN dbo.Orders o ON o.OrderID = s.OrderID
JOIN dbo.Customers c ON c.CustomerID = o.CustomerID
JOIN dbo.Regions rg ON rg.RegionID = c.RegionID
GROUP BY p.ProductID, p.ProductName, p.Category, p.Subcategory, rg.RegionID, rg.RegionName, rg.Country, o.OrderDate, o.OrderStatus, o.SalesChannel;

